using Microsoft.Extensions.Diagnostics.HealthChecks;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.AudioToText;
using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace Vivet.AI.Hosting.HealthChecks;

/// <summary>
/// Transcription Model Health Check.
/// </summary>
/// <param name="audioToTextService">The <see cref="IAudioToTextService"/>.</param>
/// <param name="promptExecutionSettings">The <see cref="PromptExecutionSettings"/>.</param>
public class TranscriptionModelHealthCheck(IAudioToTextService audioToTextService, PromptExecutionSettings promptExecutionSettings) 
    : IHealthCheck
{
    private readonly IAudioToTextService audioToTextService = audioToTextService ?? throw new ArgumentNullException(nameof(audioToTextService));
    private readonly PromptExecutionSettings promptExecutionSettings = promptExecutionSettings ?? throw new ArgumentNullException(nameof(promptExecutionSettings));

    /// <inheritdoc />
    public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context, CancellationToken cancellationToken = default)
    {
        if (context == null) 
            throw new ArgumentNullException(nameof(context));

        try
        {
            var base64 = "";
            var dataUri = $"data:audio/mp4;base64,{base64}";

            var audioContent = new AudioContent(dataUri);

            var contents = await this.audioToTextService
                .GetTextContentsAsync(audioContent, this.promptExecutionSettings, cancellationToken: cancellationToken);

            if (!contents.Any())
            {
                return HealthCheckResult.Unhealthy("No content");
            }

            return HealthCheckResult.Healthy("Success");
        }
        catch (Exception ex)
        {
            return HealthCheckResult.Unhealthy(ex.Message, ex);
        }
    }
}